-- Every positive capability below is disposable and rolls back.
\connect postgres supabase_admin
begin;
set local role postgres;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
grant usage on schema extensions to otr_trip_event_command_gateway,otr_trip_source_command_gateway,service_role;
select is((select flight_admission_enabled from public.trip_import_admission_gate),false,'Flight gate CLOSED');
select is((select capture_admission_enabled from public.trip_import_admission_gate),false,'Capture gate CLOSED');
select ok(public.trip_person_activation_security_check(true,false),'unchanged participation security verifier');
select ok(not has_table_privilege('otr_trip_event_semantic_writer','public.trip_source_confirmations','SELECT,INSERT,UPDATE,DELETE'),'B writer has no C table capability');
select ok(not has_table_privilege('otr_trip_source_writer','public.trip_event_operation_receipts','SELECT,INSERT,UPDATE,DELETE'),'C writer has no receipt table capability');
select ok(not has_table_privilege('otr_trip_event_semantic_writer','public.itinerary_transport_services','INSERT,UPDATE,DELETE'),'services deployed DML CLOSED');
set local role service_role;

